const row = $json;
const message = ((row.user_message || '') + '').trim().toLowerCase();
const userId = ((row.userId || 'anonymous') + '').trim();
const sessionId = ((row.sessionId || '') + '').trim();
const now = Date.now();
const rateWindowMs = 10 * 1000;
const maxMessages = 5;

let recentMessages = row.recentMessages || [];
if (typeof recentMessages === 'string') {
  try { recentMessages = JSON.parse(recentMessages); } catch (e) { recentMessages = []; }
}
if (!Array.isArray(recentMessages)) recentMessages = [];

const normalizedRecent = recentMessages.map(item => ({
  message: (((item && item.message) || '') + '').trim().toLowerCase(),
  timestampMs: Number((item && (item.timestampMs ?? item.timestampms ?? item.timestamp)) || 0),
}));

const recentWithinWindow = normalizedRecent.filter(item => (now - item.timestampMs) <= rateWindowMs);
const duplicateFound = recentWithinWindow.some(item => item.message === message);
const tooManyMessages = Number(row.recentCount || recentWithinWindow.length || 0) >= maxMessages;

let filterAction = 'allow';
let filterReason = '';
let reply = '';

if (!message) {
  filterAction = 'block';
  filterReason = 'Empty message';
  reply = 'Please enter a message first.';
} else if (duplicateFound) {
  filterAction = 'block';
  filterReason = 'Duplicate message detected';
  reply = 'Duplicate message detected. Please wait before sending the same message again.';
} else if (tooManyMessages) {
  filterAction = 'block';
  filterReason = 'Too many messages sent in a short time';
  reply = 'Too many messages received. Please wait a few seconds and try again.';
}

// Accuracy disclaimer cadence.
//
// Shown on the first message of a conversation, and again once the
// conversation has been idle. 30 minutes is the standard session-inactivity
// boundary in web analytics and live-chat tooling, so someone coming back
// after a break is treated as a new visit and re-informed, while a continuous
// conversation is never interrupted by it.
//
// Decided here rather than in the agent prompt on purpose: a model has no
// reliable sense of elapsed time and cannot see whether it already disclaimed
// earlier in the session, so asking it would mean either a disclaimer on every
// single reply or one that quietly stops appearing.
const IDLE_MS = 30 * 60 * 1000;
const sessionMessageCount = Number(row.sessionMessageCount || 0);
const lastMessageAtMs = Number(row.lastMessageAtMs || 0);
const showDisclaimer =
  sessionMessageCount === 0 ||
  (lastMessageAtMs > 0 && (now - lastMessageAtMs) >= IDLE_MS);

return [{ json: { userId, sessionId, user_message: message ? row.user_message : '', currentTimestamp: now, recentCount: Number(row.recentCount || recentWithinWindow.length || 0), filterAction, filterReason, filterReply: reply, showDisclaimer } }];

