const isFullPledge = $('Prepare Input').first().json.is_full_pledge === true;
const info = $('Identify Target Files').first().json;
const semantic = info.semantic || [];

// Full-document rows for files explicitly named in the question
const fullRows = $('Fetch Target File Chunks').all()
  .map(i => i.json || {})
  .filter(r => r.content && (('' + r.content).trim().length > 0))
  .filter(r => isFullPledge || ((r.access || 'public') === 'public'));

const MAX_CONTEXT = 60000; // chars; Gemini 2.5 Pro handles this comfortably
const parts = [];
let used = 0;
let sourceNo = 0;
const coveredFiles = new Set();

// 1) FULL documents for explicitly referenced files
if (fullRows.length > 0) {
  const byFile = {};
  for (const r of fullRows) {
    const key = r.file_id || r.file_name;
    (byFile[key] = byFile[key] || { name: r.file_name, folder: r.parent_folder || '', chunks: [] }).chunks.push(r);
  }
  for (const key of Object.keys(byFile)) {
    const f = byFile[key];
    f.chunks.sort((a, b) => (a.chunk_index || 0) - (b.chunk_index || 0));
    const body = f.chunks.map(c => c.content).join('\n');
    const where = f.folder ? '\nFolder: ' + f.folder : '';
    const block = 'Source ' + (sourceNo + 1) + ' (FULL DOCUMENT)\nFile: ' + (f.name || 'unknown') + where + '\n\n' + body;
    if (used + block.length > MAX_CONTEXT) { continue; }
    sourceNo++; parts.push(block); used += block.length; coveredFiles.add(key);
  }
}

// 2) Top semantic excerpts from other files (up to 15 sources total)
for (const r of semantic) {
  if (coveredFiles.has(r.fileId || r.fileName)) continue;
  const block = 'Source ' + (sourceNo + 1) + '\nFile: ' + (r.fileName || 'unknown') + '\n\n' + r.content;
  if (used + block.length > MAX_CONTEXT) break;
  sourceNo++; parts.push(block); used += block.length;
}

// 2.4) Folder listing. When the question names a date or a quoted phrase that
// matched a FOLDER, say what that folder holds. The chunks alone cannot answer
// "what is in the June 11 folder": the file inside is the May 21 minutes, and
// nothing in its text mentions June 11, so the agent used to conclude it had
// nothing and fall back.
let folderNote = '';
try {
  const patterns = JSON.parse(info.patternPayload || '[]');
  if (patterns.length) {
    const byFolder = {};
    for (const r of fullRows) {
      const folder = ('' + (r.parent_folder || '')).trim();
      if (!folder) continue;
      const hit = patterns.some(p => folder.toLowerCase().indexOf(String(p).toLowerCase()) !== -1);
      if (!hit) continue;
      if (!byFolder[folder]) byFolder[folder] = [];
      const name = r.file_name || 'unknown';
      if (byFolder[folder].indexOf(name) === -1) byFolder[folder].push(name);
    }
    const lines = Object.keys(byFolder).map(f => '"' + f + '" contains: ' + byFolder[f].join('; '));
    if (lines.length) {
      folderNote = '\n\n-----------------\n\nFOLDER CONTENTS (authoritative, from the Drive listing): ' + lines.join(' | ') +
        '. A meeting folder is named for the MEETING date and holds that meeting\'s agenda plus the PREVIOUS meeting\'s minutes, so a file dated earlier than its folder is expected and is not an error. If asked what a folder contains, answer from this listing.';
    }
  }
} catch (e) { /* patterns are optional */ }

// 2.5) Recency. Two separate facts, and they are usually DIFFERENT dates:
//   - the latest MEETING is the newest folder date (Resolve Latest Meeting)
//   - the latest MINUTES file is one meeting behind, because a meeting's folder
//     carries the previous meeting's minutes
// Answering the first with the second is the bug this section exists to stop.
let recencyNote = '';
const recencyTopic = info.recencyTopic || '';
if (recencyTopic) {
  let latestMeeting = '';
  try { latestMeeting = (($('Resolve Latest Meeting').first() || {}).json || {}).meeting_date || ''; } catch (e) { /* optional */ }

  const dated = fullRows
    .map(r => ('' + (r.file_name || '')))
    .filter(n => n.toLowerCase().indexOf(recencyTopic.toLowerCase()) !== -1 && /\d{4}-\d{2}-\d{2}/.test(n));
  // File names start with an ISO date, so a lexical sort is a date sort.
  const newestDoc = dated.length ? dated.sort().reverse()[0] : '';

  const bits = [];
  if (latestMeeting) {
    bits.push('The most recent Family Council meeting took place on ' + latestMeeting + '. Each meeting has its own folder named for the meeting date, holding that meeting\'s agenda and the PREVIOUS meeting\'s minutes, so the newest minutes document is always one meeting behind. If asked when the last meeting was, answer ' + latestMeeting + ' and do NOT answer with the date on the newest minutes file.');
  }
  if (newestDoc) {
    bits.push('The newest ' + recencyTopic + ' document held is "' + newestDoc + '", included above in full; if minutes for the latest meeting are not present, say they are not available yet.');
  }
  bits.push('A date written inside a document, such as a future meeting being scheduled, is not authoritative unless it matches the above.');
  if (bits.length) recencyNote = '\n\n-----------------\n\nNOTE: ' + bits.join(' ');
}

// 2.6) An image the user pasted with THIS message, transcribed by vision.
// User-supplied, not Knowledge Base content - the prompt says so as well,
// otherwise the answer-only-from-the-KB rule makes the agent refuse to discuss
// the very screenshot the user just sent.
let chatImageNote = '';
try {
  const described = (($('Describe Chat Image').first() || {}).json || {});
  const text = ('' + (described.text || described.output || described.response || '')).trim();
  if (text) {
    chatImageNote = '\n\n-----------------\n\nIMAGE SENT BY THE USER WITH THIS MESSAGE (transcribed automatically, provided by the user rather than the Knowledge Base):\n' + text;
  }
} catch (e) { /* no image on this message - the vision branch did not run */ }

// 3) Tell the agent which files have stored images (attached automatically below its answer)
let imageNote = '';
try {
  const imgs = $('Fetch Related Images').all()
    .map(it => it.json || {})
    .filter(r => r.file_id && (isFullPledge || ((r.access || 'public') === 'public')));
  const names = [...new Set(imgs.map(r => r.file_name))];
  if (names.length) {
    imageNote = '\n\n-----------------\n\nNOTE: The following document images will be automatically attached below your answer: ' + names.join('; ') + '. Refer to them naturally (e.g. "see the attached document image(s) below") instead of saying no information is available for these files.';
  }
} catch (e) { /* images optional */ }

const context = (parts.length ? parts.join('\n\n-----------------\n\n') : 'No relevant Knowledge Base content was found for this question.') + folderNote + recencyNote + chatImageNote + imageNote;
return [{ json: { context } }];

const userMessage = (($('Apply Filter Logic').first().json.user_message || '') + '').toLowerCase();
const isFullPledge = $('Prepare Input').first().json.is_full_pledge === true;

const rows = $input.all()
  .map(i => {
    const d = (i.json && i.json.document) ? i.json.document : (i.json || {});
    return {
      content: d.pageContent || d.text || d.content || '',
      meta: d.metadata || i.json.metadata || {},
      score: Number(i.json.score || 999)
    };
  })
  .filter(r => r.content && r.content.trim().length > 0)
  // Deterministic access enforcement: non full-pledge users only ever get public chunks
  .filter(r => isFullPledge || ((r.meta.access || 'public') === 'public'));

// Filename-aware boost: question mentions a file name or its date
function boostFor(fileName) {
  const name = ((fileName || '') + '').toLowerCase().replace(/\.[a-z0-9]+$/, '');
  if (!name) return 0;
  let boost = 0;
  if (userMessage.includes(name)) boost += 100;
  const dateMatch = name.match(/\d{4}-\d{2}-\d{2}/);
  if (dateMatch && userMessage.includes(dateMatch[0])) boost += 50;
  const tokens = name.split(/[^a-z0-9]+/).filter(t => t.length >= 5);
  for (const t of tokens) { if (userMessage.includes(t)) boost += 1; }
  return boost;
}
for (const r of rows) r.boost = boostFor(r.meta.fileName);
rows.sort((a, b) => (b.boost - a.boost) || (a.score - b.score));

// 1) Files explicitly referenced among the retrieved results get their FULL content fetched
const targetIds = [];
for (const r of rows) {
  if (r.boost >= 50 && r.meta.fileId && !targetIds.includes(r.meta.fileId)) targetIds.push(r.meta.fileId);
  if (targetIds.length >= 3) break;
}

// 2) Direct name/date patterns from the question, independent of semantic
//    retrieval. 'Fetch Target File Chunks' matches these against BOTH file
//    names and folder names, so a date that names a meeting pulls in whatever
//    lives in that meeting's folder.
const namePatterns = [];
function addPattern(p) {
  const clean = ('' + p).trim();
  if (clean && !namePatterns.includes(clean)) namePatterns.push(clean);
}

// 2a) ISO dates, written as they appear in file and folder names
for (const d of (userMessage.match(/\d{4}-\d{2}-\d{2}/g) || [])) addPattern(d);

// 2b) Plain English dates. People ask about "the june 11 2026 meeting", not
//     "2026-06-11", and before this nothing was extracted from that at all -
//     the question produced no pattern and the folder was never consulted.
const MONTHS = {
  january: 1, jan: 1, february: 2, feb: 2, march: 3, mar: 3, april: 4, apr: 4,
  may: 5, june: 6, jun: 6, july: 7, jul: 7, august: 8, aug: 8,
  september: 9, sept: 9, sep: 9, october: 10, oct: 10, november: 11, nov: 11,
  december: 12, dec: 12
};
function iso(year, month, day) {
  return year + '-' + String(month).padStart(2, '0') + '-' + String(day).padStart(2, '0');
}
let m;
// "june 11 2026", "june 11th, 2026"
const monthFirst = /\b([a-z]{3,9})\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b/g;
while ((m = monthFirst.exec(userMessage)) !== null) {
  const mo = MONTHS[m[1]];
  if (mo) addPattern(iso(m[3], mo, m[2]));
}
// "11 june 2026", "11th of june 2026"
const dayFirst = /\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([a-z]{3,9}),?\s+(\d{4})\b/g;
while ((m = dayFirst.exec(userMessage)) !== null) {
  const mo = MONTHS[m[2]];
  if (mo) addPattern(iso(m[3], mo, m[1]));
}

// 2c) "quoted names" are looked up straight in the DB
for (const q of (userMessage.match(/"([^"]{4,80})"/g) || [])) addPattern(q.replace(/"/g, ''));

// 3) Recency intent.
//    Semantic search has no notion of dates: every set of Family Council
//    Minutes reads almost identically, so "when was the last FC meeting?"
//    returned whichever year happened to rank. Detect the intent here;
//    'Fetch Target File Chunks' resolves the newest matching file from the ISO
//    date in its name, which needs no date metadata and so needed no
//    re-embedding.
const RECENCY_RE = /\b(latest|last|most recent|newest|current|up[- ]to[- ]date)\b/;
const TOPIC_RULES = [
  // agenda first: "the last meeting agenda" wants the agenda, not the minutes
  { re: /\bagenda\b/, topic: 'Family Council Agenda' },
  { re: /\b(minutes|meeting|meetings)\b/, topic: 'Family Council Minutes' }
];
let recencyTopic = '';
if (RECENCY_RE.test(userMessage)) {
  for (const rule of TOPIC_RULES) {
    if (rule.re.test(userMessage)) { recencyTopic = rule.topic; break; }
  }
}

return [{ json: {
  targetFileIds: targetIds,
  targetPayload: JSON.stringify(targetIds),
  patternPayload: JSON.stringify(namePatterns.slice(0, 5)),
  recencyTopic: recencyTopic,
  semantic: rows.slice(0, 15).map(r => ({
    content: r.content,
    fileName: r.meta.fileName || 'unknown',
    fileId: r.meta.fileId || '',
    access: r.meta.access || 'public',
    chunkIndex: Number(r.meta.chunkIndex || 0)
  }))
} }];

// Convert the agent's Markdown answer into clean HTML for the portal chat widget
const raw = ($json.output || $json.text || $json.response || '') + '';

function esc(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function inline(s) {
  return s.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
}

const lines = raw.split(/\r?\n/);
const out = [];
let i = 0;
let listTag = null;
function closeList() {
  if (listTag) { out.push('</' + listTag + '>'); listTag = null; }
}

while (i < lines.length) {
  const t = lines[i].trim();

  // Markdown table block -> HTML table
  if (t.startsWith('|') && t.endsWith('|')) {
    closeList();
    const tbl = [];
    while (i < lines.length && lines[i].trim().startsWith('|')) { tbl.push(lines[i].trim()); i++; }
    const rows = tbl
      .filter(r => !/^\|[\s:\-|]+\|$/.test(r))
      .map(r => r.replace(/^\||\|$/g, '').split('|').map(c => inline(esc(c.trim()))));
    if (rows.length) {
      let html = '<table style="border-collapse:collapse;margin:8px 0">';
      rows.forEach((cells, idx) => {
        const tag = idx === 0 ? 'th' : 'td';
        const style = 'border:1px solid #888;padding:4px 10px;text-align:left' + (idx === 0 ? ';font-weight:bold;background:rgba(128,128,128,0.2)' : '');
        html += '<tr>' + cells.map(c => '<' + tag + ' style="' + style + '">' + c + '</' + tag + '>').join('') + '</tr>';
      });
      html += '</table>';
      out.push(html);
    }
    continue;
  }

  // Headings (#, ##, ###)
  const h = t.match(/^#{1,4}\s+(.*)$/);
  if (h) {
    closeList();
    out.push('<div style="font-weight:bold;font-size:1.08em;margin:12px 0 4px">' + inline(esc(h[1])) + '</div>');
    i++; continue;
  }

  // Bullet list items (- or *)
  const b = t.match(/^[-*]\s+(.*)$/);
  if (b) {
    if (listTag !== 'ul') { closeList(); out.push('<ul style="margin:4px 0;padding-left:20px">'); listTag = 'ul'; }
    out.push('<li style="margin:3px 0">' + inline(esc(b[1])) + '</li>');
    i++; continue;
  }

  // Numbered list items (1. / 1))
  const n = t.match(/^\d+[.)]\s+(.*)$/);
  if (n) {
    if (listTag !== 'ol') { closeList(); out.push('<ol style="margin:4px 0;padding-left:20px">'); listTag = 'ol'; }
    out.push('<li style="margin:3px 0">' + inline(esc(n[1])) + '</li>');
    i++; continue;
  }

  // Blank line ends any open list
  if (t === '') { closeList(); i++; continue; }

  // Regular paragraph
  closeList();
  out.push('<p style="margin:6px 0">' + inline(esc(t)) + '</p>');
  i++;
}
closeList();

// Attach stored document images (image files + scanned PDF pages) below the answer
try {
  const isFullPledge = $('Prepare Input').first().json.is_full_pledge === true;
  const BASE = 'https://N8N_HOST_REDACTED/webhook/REDACTED';
  const imgs = $('Fetch Related Images').all()
    .map(it => it.json || {})
    .filter(r => r.file_id && (isFullPledge || ((r.access || 'public') === 'public')));
  if (imgs.length) {
    out.push('<div style="font-weight:bold;font-size:1.08em;margin:14px 0 4px">Attached document images</div>');
    let lastFile = '';
    for (const im of imgs.slice(0, 8)) {
      if (im.file_name !== lastFile) {
        out.push('<p style="margin:8px 0 2px"><b>' + esc(String(im.file_name || '')) + '</b></p>');
        lastFile = im.file_name;
      }
      out.push('<img src="' + BASE + '?fid=' + encodeURIComponent(im.file_id) + '&page=' + (Number(im.page) || 1) + '" style="max-width:100%;border:1px solid #888;border-radius:6px;margin:4px 0" alt="' + esc(String(im.file_name || 'document image')) + '"/>');
    }
  }
} catch (e) { /* images are optional - never break the reply */ }

// Accuracy disclaimer. 'Apply Filter Logic' decides WHEN: first message of a
// conversation, or the first message back after 30 minutes of silence.
//
// Appended BELOW the answer, under a hairline rule, and labelled 'Disclaimer:'
// so it is named rather than reading as unexplained small print. As a filled
// panel above the answer it looked like a separate incoming message.
//
// Built here rather than asked of the model so the wording is exact and cannot
// drift; the agent prompt separately forbids it writing its own.
let disclaimer = '';
try {
  if ($('Apply Filter Logic').first().json.showDisclaimer === true) {
    disclaimer =
      '<p style="margin:12px 0 0;padding-top:8px;border-top:1px solid rgba(128,128,128,0.35);' +
      'font-size:0.85em;line-height:1.45;opacity:0.75">' +
      '<b>Disclaimer:</b> ' +
      'The MFC Chatbot is here to help, but its responses may not always be complete or fully accurate. ' +
      'If you have any questions or need further clarification, please feel free to check directly with the Family Council.' +
      '</p>';
  }
} catch (e) { /* never withhold an answer because the flag was unreadable */ }

return [{ json: { output: out.join('') + disclaimer, output_markdown: raw } }];

// Turn the stored base64 into a real image binary for the webhook response
const row = ($input.first() && $input.first().json) || {};
let b64 = row.image_base64;
let mime = row.mime_type || 'image/jpeg';
let name = row.file_name || 'image.jpg';
if (!b64) {
  // 1x1 transparent PNG fallback so missing images never break the page
  b64 = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';
  mime = 'image/png';
  name = 'not-found.png';
}
const binary = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), name, mime);
return [{ json: { file_name: name }, binary: { data: binary } }];
